#include <iostream>
#include <mutex>
#include <thread>
#include <vector>

long total = 0;
std::mutex m;

void work() {
    for (int k = 0; k < 2500; ++k) {
        std::lock_guard<std::mutex> lk(m);   // RAII 加锁，作用域结束自动解锁
        ++total;
    }
}

int main() {
    std::vector<std::thread> ts;
    for (int i = 0; i < 4; ++i) ts.emplace_back(work);
    for (auto& t : ts) t.join();
    std::cout << "total=" << total;   // 4*2500=10000，确定性
}
